import 'package:flutter/material.dart';
import 'activity_repository.dart';
class ActivityScreen extends StatefulWidget { const ActivityScreen({super.key, required this.repository}); final ActivityRepository repository; @override State<ActivityScreen> createState()=>_ActivityScreenState(); }
class _ActivityScreenState extends State<ActivityScreen> { bool done=false; @override void initState(){super.initState();done=widget.repository.isDone(DateTime.now());} Future<void> toggle() async { final next=!done; await widget.repository.setDone(DateTime.now(),next); if(mounted)setState(()=>done=next); } @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Aufgabe des Tages')),body:Center(child:Padding(padding:const EdgeInsets.all(24),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(done?Icons.check_circle:Icons.directions_walk,size:80,color:Theme.of(c).colorScheme.primary),const SizedBox(height:20),Text(done?'Erledigt!':'15 Minuten spazieren gehen',style:Theme.of(c).textTheme.headlineSmall,textAlign:TextAlign.center),const SizedBox(height:20),FilledButton(onPressed:toggle,child:Text(done?'Als offen markieren':'Erledigt markieren'))])))); }
